import os
import json
import time
import random
import warnings
import torch
import numpy as np
import jieba.posseg as psg  # 仅导入一次
from typing import Any, Dict
from flask import Flask, request, jsonify

psg.lcut('测试')  # 预加载，避免第一次加载耗时过长
warnings.filterwarnings('ignore')

from config.config import CONFIG

from src.doc_compress import DocCompressor
from src.text_selecter import TextSummarizer
from src.model_extractor import model_extractor
from src.chunkers import TextChunker

from util.log_tool import logger


### SEEDS&TRACEID ###
def same_seeds(seed: int, use_torch: bool = False) -> None:
    # 设置随机种子，保证结果可重复
    os.environ['PYTHONHASHSEED'] = str(seed)
    np.random.seed(seed)
    random.seed(seed)
    if use_torch:
        if torch.cuda.is_available():
            torch.cuda.manual_seed(seed)
            torch.cuda.manual_seed_all(seed)
        torch.manual_seed(seed)
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False
        torch.backends.cudnn.enabled = False

def generate_trace_id(query: str) -> str:
    # 生成唯一的trace_id，用查询作为种子
    random.seed('trace-' + query)
    trace_id = str(random.randint(100000000, 999999999))
    random.seed(config_app.SEED)
    return trace_id


try:
    # 创建Flask应用
    app = Flask(__name__)
    # 初始化配置和日志
    config_app = CONFIG(logger=logger)
    logger.info("[--- Text Summary ---] Start loading model...")
    same_seeds(config_app.SEED)
    # 初始化文本摘要器
    text_summarizer = TextSummarizer(logger=logger)
    # 初始化文档压缩类实例
    doc_compressor = DocCompressor()
    # 初始化文本分块器
    chunker = TextChunker()
    logger.info("[--- Text Summary ---] Model loaded successfully！！！")
except Exception as e:
    logger.exception()


@app.route('/text-summary', methods=['POST'])
def text_summary():
    """文本摘要接口

    接收POST请求，从请求体中提取'text'和可选的'mode'参数。
    根据语言和模式调用相应模型进行摘要生成。

    Returns:
        Flask Response: 包含状态码、消息、数据和traceId的JSON响应。
    """
    start_time = time.time()

    # 获取请求参数
    try:
        input_data = json.loads(request.data)
    except json.JSONDecodeError:
        return jsonify({'code': 400, 'message': 'Invalid JSON input', 'data': {}, 'traceId': ''})

    logger.info(f" [--- 批量关键词提取器 --- ] 接收到的参数帧长度为 {len(input_data)}")

    trace_id = generate_trace_id(str(input_data))
    trace_id = input_data.get('traceId', trace_id)
    mode = input_data.get('mode', 0)  # 默认抽取摘要模式

    response_data: Dict[str, Any] = {
        'code': 200,
        'message': 'Success',
        'data': {},
        'traceId': trace_id
    }

    try:
        logger.info(f"[--- Text Summary ---] Received params.")
        text = input_data.get('text', None)
        if not text or not isinstance(text, str):
            raise ValueError("Text field is required and must be string")

        # 根据模式生成摘要
        if mode == 0:
            # 抽取式摘要
            summary = text_summarizer.compress_text(doc=text)
            response_data['data']['summary'] = summary
        else:
            summary = model_extractor.generate_summaries(text)
            response_data['data']['summary'] = summary

    except Exception as e:
        logger.exception()
        response_data.update({
            'code': 500,
            'message': str(e),
            'data': {}
        })

    finally:
        end_time = time.time()
        exec_time = round((end_time - start_time) * 1000, 2)
        logger.info(f'Execution Time: {exec_time} ms')

    return jsonify(response_data)


