@app.route('/doc-compress', methods=['POST'])
def doc_compress_api():
    start_time = time.time()

    try:
        input_data = json.loads(request.data)
    except json.JSONDecodeError:
        return jsonify({'code': 400, 'message': 'Invalid JSON input', 'data': {}, 'traceId': ''})

    logger.info(f"[--- Doc Compress ---] Received params.")
    trace_id = generate_trace_id(str(input_data))
    trace_id = input_data.get('traceId', trace_id)

    response_data: Dict[str, Any] = {
        'code': 200,
        'message': 'Success',
        'data': {},
        'traceId': trace_id
    }
    try:
        text = input_data.get('text', None)
        if not text or not isinstance(text, str):
            raise ValueError("Text field is required and must be a string")
        query = input_data.get('query', None)
        method = input_data.get('method', 'fast')  # 默认使用fast_compress
        topN = input_data.get('topN', 3) if isinstance(input_data.get('topN'), int) else 3
        text_type = input_data.get('type', 'general')  # 默认为文档类型
        compressed_text = doc_compressor.compress(doc=text, query=query, method=method, topN=topN, text_type=text_type)
        response_data['data']['compressed_text'] = compressed_text
    except Exception as e:
        logger.exception()
        response_data.update({
            'code': 500,
            'message': str(e),
            'data': {}
        })
    finally:
        end_time = time.time()
        exec_time = round((end_time - start_time) * 1000, 2)
        logger.info(f'Execution Time: {exec_time} ms')

    return jsonify(response_data)


@app.route('/doc-chunk', methods=['POST'])
def chunk_app():
    start_time = time.time()
    try:
        input_data = json.loads(request.data)
    except json.JSONDecodeError:
        return jsonify({'code': 400, 'message': 'Invalid JSON input', 'data': {}, 'traceId': ''})

    logger.info(f"[--- Doc Chunk ---] Received params.")
    trace_id = generate_trace_id(str(input_data))
    trace_id = input_data.get('traceId', trace_id)

    response_data: Dict[str, Any] = {
        'code': 200,
        'message': 'Success',
        'data': {},
        'traceId': trace_id
    }
    try:
        text = input_data.get('text', None)
        if not text or not isinstance(text, str):
            raise ValueError("Text field is required and must be a string")
        chunk_type = str(input_data.get('method', "paragraph")).lower()
        assert chunk_type in ['paragraph', 'sentence', 'semantic'], "Invalid chunk type"
        chunks = chunker.chunk_text(text, chunk_type)
        response_data['data']['chunks'] = chunks
    except Exception as e:
        logger.exception()
        response_data.update({
            'code': 500,
            'message': str(e),
            'data': {}
        })
    finally:
        end_time = time.time()
        exec_time = round((end_time - start_time) * 1000, 2)
        logger.info(f'Execution Time: {exec_time} ms')
    return jsonify(response_data)


if __name__ == '__main__':
    # 启动Flask服务
    # 可根据需要调整host和port
    app.run(host='0.0.0.0', port=config_app.PORT)
